  let mtime_ms = null;
  if (Number.isFinite(seconds) && seconds > 0) {
    let milliseconds = 0;
    if (separator >= 0) {
      const fraction = first.slice(separator + 1).match(/\.(\d{1,9})(?:\s|$)/);
      if (fraction) milliseconds = Number((fraction[1] + "000").slice(0, 3));
